<?php
include("auth_owner.php");include("db.php");include("functions.php");$notice='';$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){
 $rid=(int)($_POST['request_id']??0);$action=$_POST['action']??'';
 $stmt=mysqli_prepare($conn,"SELECT rr.*,i.owner_id,i.item_id,i.status item_status FROM rental_requests rr JOIN items i ON i.item_id=rr.item_id WHERE rr.request_id=? AND i.owner_id=? LIMIT 1");mysqli_stmt_bind_param($stmt,"ii",$rid,$owner_id);mysqli_stmt_execute($stmt);$req=mysqli_fetch_assoc(mysqli_stmt_get_result($stmt));mysqli_stmt_close($stmt);
 if(!$req)$error="Request not found.";elseif($action==='approve'&&$req['status']==='pending'){mysqli_begin_transaction($conn);try{$stmt=mysqli_prepare($conn,"UPDATE rental_requests SET status='approved' WHERE request_id=?");mysqli_stmt_bind_param($stmt,"i",$rid);mysqli_stmt_execute($stmt);mysqli_stmt_close($stmt);$stmt=mysqli_prepare($conn,"UPDATE items SET status='rented' WHERE item_id=? AND owner_id=?");mysqli_stmt_bind_param($stmt,"ii",$req['item_id'],$owner_id);mysqli_stmt_execute($stmt);mysqli_stmt_close($stmt);$stmt=mysqli_prepare($conn,"UPDATE rental_requests SET status='rejected' WHERE item_id=? AND request_id<>? AND status='pending'");mysqli_stmt_bind_param($stmt,"ii",$req['item_id'],$rid);mysqli_stmt_execute($stmt);mysqli_stmt_close($stmt);mysqli_commit($conn);$notice="Request approved. Other pending requests for this item were rejected.";}catch(Throwable $ex){mysqli_rollback($conn);$error=$ex->getMessage();}}
 elseif($action==='reject'&&$req['status']==='pending'){$stmt=mysqli_prepare($conn,"UPDATE rental_requests SET status='rejected' WHERE request_id=?");mysqli_stmt_bind_param($stmt,"i",$rid);mysqli_stmt_execute($stmt);mysqli_stmt_close($stmt);$notice="Request rejected.";}
 elseif($action==='complete'&&$req['status']==='approved'){mysqli_begin_transaction($conn);try{$stmt=mysqli_prepare($conn,"UPDATE rental_requests SET status='completed' WHERE request_id=?");mysqli_stmt_bind_param($stmt,"i",$rid);mysqli_stmt_execute($stmt);mysqli_stmt_close($stmt);$stmt=mysqli_prepare($conn,"UPDATE items SET status='available' WHERE item_id=? AND owner_id=?");mysqli_stmt_bind_param($stmt,"ii",$req['item_id'],$owner_id);mysqli_stmt_execute($stmt);mysqli_stmt_close($stmt);mysqli_commit($conn);$notice="Rental marked completed and item is available again.";}catch(Throwable $ex){mysqli_rollback($conn);$error=$ex->getMessage();}}
 else $error="That action is not available for the current request status.";
}
$filter=$_GET['status']??'all';$valid=['all','pending','approved','completed','rejected','cancelled'];if(!in_array($filter,$valid,true))$filter='all';$sql="SELECT rr.*,i.item_name,i.rental_price,i.security_deposit,p.full_name, EXISTS(SELECT 1 FROM payments pay WHERE pay.booking_id=rr.request_id AND pay.status='completed') AS is_paid FROM rental_requests rr JOIN items i ON i.item_id=rr.item_id LEFT JOIN user_profiles p ON p.user_id=rr.borrower_id WHERE i.owner_id=?";if($filter!=='all')$sql.=" AND rr.status=?";$sql.=" ORDER BY rr.request_id DESC";$stmt=mysqli_prepare($conn,$sql);if($filter==='all')mysqli_stmt_bind_param($stmt,"i",$owner_id);else mysqli_stmt_bind_param($stmt,"is",$owner_id,$filter);mysqli_stmt_execute($stmt);$res=mysqli_stmt_get_result($stmt);$rows=[];while($x=mysqli_fetch_assoc($res))$rows[]=$x;mysqli_stmt_close($stmt);$current='requests';
?>
<!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1.0"><title>Rental Requests | BorrowBee</title><link rel="stylesheet" href="style.css"></head><body class="app-body"><div class="app-layout"><?php include("owner_sidebar.php"); ?><main class="main-content"><header class="topbar"><div><h1>Rental Requests</h1><p class="topbar-sub">Approve, reject and complete rentals for your items.</p></div></header><?php if($notice):?><div class="success-msg"><?php echo e($notice); ?></div><?php endif;?><?php if($error):?><div class="error-msg"><?php echo e($error); ?></div><?php endif;?><div class="filter-tabs"><?php foreach($valid as $f):?><a class="filter-tab <?php echo $filter===$f?'active':''; ?>" href="owner_requests.php?status=<?php echo e($f); ?>"><?php echo e(ucfirst($f)); ?></a><?php endforeach;?></div><section class="panel"><div class="table-scroll"><table class="data-table"><thead><tr><th>Request</th><th>Borrower</th><th>Item</th><th>Dates / Amount</th><th>Status</th><th>Action</th></tr></thead><tbody><?php if(!$rows):?><tr><td colspan="6">No requests found.</td></tr><?php endif;?><?php foreach($rows as $r):$total=rental_total($r['start_date'],$r['end_date'],$r['rental_price'],$r['security_deposit']);?><tr><td>#<?php echo (int)$r['request_id']; ?></td><td><?php echo e($r['full_name']?:('User #'.$r['borrower_id'])); ?></td><td><strong><?php echo e($r['item_name']); ?></strong><small><?php echo e($r['message']); ?></small></td><td><?php echo e($r['start_date']); ?> → <?php echo e($r['end_date']); ?><small>৳<?php echo number_format($total,2); ?></small></td><td><span class="status-pill status-<?php echo e($r['status']); ?>"><?php echo e(ucfirst($r['status'])); ?></span><?php if($r['is_paid']):?><small class="paid-text">Paid ✓</small><?php endif;?></td><td><div class="owner-actions"><?php if($r['status']==='pending'):?><form method="post"><input type="hidden" name="request_id" value="<?php echo (int)$r['request_id']; ?>"><button class="owner-btn owner-btn-edit" name="action" value="approve">Approve</button><button class="owner-btn owner-btn-danger" name="action" value="reject">Reject</button></form><?php elseif($r['status']==='approved'):?><form method="post"><input type="hidden" name="request_id" value="<?php echo (int)$r['request_id']; ?>"><button class="owner-btn owner-btn-neutral" name="action" value="complete">Mark Completed</button></form><?php else:?>—<?php endif;?></div></td></tr><?php endforeach;?></tbody></table></div></section></main></div></body></html>
